// The deployed app starts empty; classes and attendance are loaded securely
// from the teacher's Supabase workspace after the teacher signs in.
const defaultData = { classes: [], attendance: {} };
let db = JSON.parse(localStorage.getItem('classcheck-data') || 'null') || defaultData;
db.community ||= {};
db.homework ||= {};
db.parentAccess ||= {};
db.teacherProfile ||= {about:'I help students build confident English communication through practical, supportive lessons.',ielts:'',experience:''};
db.studentProfiles ||= {};
db.results ||= {};
let screen = new URLSearchParams(location.search).has('teacher') ? 'teacher-login' : 'login', selectedClass = 'b1', selectedDate = today(), parentStudent = 'Amir Karimov', parentClass = 'b1', parentMonth = '2026-08', language = localStorage.getItem('classcheck-language') || 'UZB';
let communityClass = 'b1', communityReturn = 'teacher';
let authAccess = null, loginStep = 'phone', accessStudent = '';
let parentSession = null, parentStudentId = null;
let profileStudent = '', profileClass = '', profileReturn = 'parent', profileEditable = false, teacherProfileReturn = 'parent';
let teacherSession = null, onlineStudents = [];
const $ = s => document.querySelector(s);
function save(){localStorage.setItem('classcheck-data',JSON.stringify(db))}
function today(){return new Date().toISOString().slice(0,10)}
function locale(){return language==='UZB'?'uz-UZ':'en-GB'}
function fmtDate(d){return new Date(d+'T12:00:00').toLocaleDateString(locale(),{weekday:'short',day:'numeric',month:'short'})}
function attendanceFor(c,d){return db.attendance[`${c}|${d}`] || {}}
function setAttendance(c,d,name,status){let key=`${c}|${d}`;db.attendance[key] ||= {};db.attendance[key][name]=status;save();persistOnlineAttendance(c,d,name,status)}
async function persistOnlineAttendance(classId,lessonDate,studentName,status){if(!teacherSession||!window.classcheckSupabase)return;const student=onlineStudents.find(item=>item.group_id===classId&&item.full_name===studentName);if(!student)return;const {error}=await window.classcheckSupabase.from('attendance').upsert({student_id:student.id,lesson_date:lessonDate,status,marked_by:teacherSession.user.id},{onConflict:'student_id,lesson_date'});if(error)console.error('Attendance sync failed',error.message)}
function classById(id){return db.classes.find(c=>c.id===id)}
function allDatesForClass(c){return Object.keys(db.attendance).filter(k=>k.startsWith(c+'|')).map(k=>k.split('|')[1]).sort()}
function rate(c,student){const records=allDatesForClass(c).map(d=>attendanceFor(c,d)[student]).filter(Boolean);return records.length ? Math.round(records.filter(x=>x==='present').length/records.length*100) : 0}
function teacher(){const cls=classById(selectedClass), record=attendanceFor(selectedClass,selectedDate);let present=cls.students.filter(s=>record[s]==='present').length, classRate=cls.students.length?Math.round(cls.students.reduce((a,s)=>a+rate(selectedClass,s),0)/cls.students.length):0;return `<div class="shell"><header class="topbar"><div class="brand"><i class="brand-mark"></i>ClassCheck</div><div class="account"><div><strong style="font-size:13px">Teacher workspace</strong><div class="role">Attendance manager</div></div><div class="avatar">TC</div></div></header><main class="main"><div class="hero"><div><div class="eyebrow">Your teaching centre</div><h1>Good afternoon, Teacher.</h1><p>Keep your classes organised and your families informed.</p></div><button class="btn primary" onclick="openClassModal()">+ Add a class</button></div><div class="dashboard"><aside class="sidebar"><div><div class="nav-label">Workspace</div><button class="nav-item active"><span class="nav-icon">▦</span>Attendance</button><button class="nav-item" onclick="showParentLogin()"><span class="nav-icon">↗</span>Parent view</button></div><div class="side-section"><div class="nav-label">Your classes</div>${db.classes.map(c=>`<button class="nav-item ${c.id===selectedClass?'active':''}" onclick="selectedClass='${c.id}';render()"><span class="nav-icon">◉</span>${c.name}</button>`).join('')}</div></aside><section class="content"><div class="overview-cards"><div class="stat"><div class="stat-label">Students in ${cls.name}</div><div class="stat-value">${cls.students.length}</div><small>Currently enrolled</small></div><div class="stat"><div class="stat-label">Marked present today</div><div class="stat-value">${present}<span style="font-family:DM Sans;font-size:17px;color:#9aa39d"> / ${cls.students.length}</span></div><small>${present ? 'Attendance in progress' : 'Ready to take attendance'}</small></div><div class="stat"><div class="stat-label">Class attendance rate</div><div class="stat-value">${classRate}%</div><small>Across marked lessons</small></div></div><div class="attendance-box"><div class="attendance-toolbar"><div><h2 class="section-title">Take attendance</h2><p class="section-subtitle">${cls.name} · ${cls.level}</p></div><div class="date-picker"><span class="role">Lesson date</span><input type="date" value="${selectedDate}" onchange="selectedDate=this.value;render()"></div></div><div class="table-wrap"><table class="teacher-table"><thead><tr><th>Student</th><th>Attendance</th><th>Current rate</th></tr></thead><tbody>${cls.students.map(s=>`<tr><td><div class="student-name">${s}</div><div class="student-note">${cls.name}</div></td><td><div class="attendance-toggle"><button class="status-btn present ${record[s]==='present'?'selected':''}" title="Present" onclick="setAttendance('${selectedClass}','${selectedDate}','${s}','present');render()">✓</button><button class="status-btn absent ${record[s]==='absent'?'selected':''}" title="Absent" onclick="setAttendance('${selectedClass}','${selectedDate}','${s}','absent');render()">×</button>${record[s]?`<span class="status-text ${record[s]}">${record[s]==='present'?'Present':'Absent'}</span>`:''}</div></td><td><strong>${rate(selectedClass,s)}%</strong></td></tr>`).join('')}</tbody></table></div><button class="add-row" onclick="openStudentModal()">+ Add student to ${cls.name}</button></div></section></div></main></div>`}
function showParentLogin(){language='UZB';localStorage.setItem('classcheck-language',language);screen='login';render()}
function teacherLoginPage(){return `<div class="login-page teacher-login"><section class="login-visual"><div class="brand"><i class="brand-mark"></i>Teacher Muhammaddiyor</div><div><h1>Teacher <em>workspace.</em></h1><p>Secure access for attendance, groups, results, and your professional profile.</p></div><div class="quote">Private teacher access</div></section><section class="login-panel"><div class="login-form"><div class="eyebrow">Teacher access</div><h2>Welcome back.</h2><p>Sign in with the private account you created in Supabase.</p><div class="field"><label>Email</label><input id="teacher-email" type="email" placeholder="Your email address" /></div><div class="field"><label>Password</label><input id="teacher-password" type="password" placeholder="Your password" onkeydown="if(event.key==='Enter')signInTeacher()" /></div><div class="notice" id="teacher-login-notice"></div><button class="btn primary" onclick="signInTeacher()">Sign in →</button></div></section></div>`}
async function loadOnlineWorkspace(){const client=window.classcheckSupabase,teacherId=teacherSession.user.id;let {data:groups,error}=await client.from('groups').select('*').eq('teacher_id',teacherId).order('created_at');if(error)throw error;if(!groups.length){for(const localGroup of db.classes){const {data:group,error:groupError}=await client.from('groups').insert({name:localGroup.name,level:localGroup.level,teacher_id:teacherId}).select().single();if(groupError)throw groupError;for(const studentName of localGroup.students){const {data:student,error:studentError}=await client.from('students').insert({group_id:group.id,full_name:studentName}).select().single();if(studentError)throw studentError;for(const [key,record] of Object.entries(db.attendance)){if(!key.startsWith(localGroup.id+'|')||!record[studentName])continue;const lessonDate=key.split('|')[1];await client.from('attendance').insert({student_id:student.id,lesson_date:lessonDate,status:record[studentName],marked_by:teacherId})}}}({data:groups,error}=await client.from('groups').select('*').eq('teacher_id',teacherId).order('created_at'));if(error)throw error}const groupIds=groups.map(group=>group.id);const {data:students,error:studentsError}=await client.from('students').select('*').in('group_id',groupIds);if(studentsError)throw studentsError;onlineStudents=students;const studentIds=students.map(student=>student.id);const {data:attendance,error:attendanceError}=studentIds.length?await client.from('attendance').select('*').in('student_id',studentIds):{data:[],error:null};if(attendanceError)throw attendanceError;db.classes=groups.map(group=>({id:group.id,name:group.name,level:group.level||'English',students:students.filter(student=>student.group_id===group.id).map(student=>student.full_name)}));db.attendance={};attendance.forEach(record=>{const student=students.find(item=>item.id===record.student_id);if(!student)return;const key=`${student.group_id}|${record.lesson_date}`;db.attendance[key]||={};db.attendance[key][student.full_name]=record.status});selectedClass=db.classes[0]?.id||selectedClass;save()}
async function signInTeacher(){if(!window.classcheckSupabase){$('#teacher-login-notice').textContent='Online connection is loading. Please refresh and try again.';$('#teacher-login-notice').classList.add('show');return}const email=$('#teacher-email').value.trim(),password=$('#teacher-password').value;if(!email||!password){$('#teacher-login-notice').textContent='Enter your email and password.';$('#teacher-login-notice').classList.add('show');return}const {data,error}=await window.classcheckSupabase.auth.signInWithPassword({email,password});if(error){const reason=error.message==='Email not confirmed'?'Email tasdiqlanmagan. Supabase ichida email tasdiqlashni o‘chiring yoki emaildagi tasdiqlash havolasini bosing.':error.message==='Invalid login credentials'?'Email yoki parol noto‘g‘ri. Parolni Supabase Authentication → Users orqali yangilab ko‘ring.':`Kirish amalga oshmadi: ${error.message}`;$('#teacher-login-notice').textContent=reason;$('#teacher-login-notice').classList.add('show');return}const {data:profile,error:profileError}=await window.classcheckSupabase.from('profiles').select('role').eq('id',data.user.id).single();if(profileError||profile?.role!=='teacher'){await window.classcheckSupabase.auth.signOut();$('#teacher-login-notice').textContent='This account does not have teacher access.';$('#teacher-login-notice').classList.add('show');return}teacherSession=data.session;try{await loadOnlineWorkspace()}catch(syncError){console.error(syncError);$('#teacher-login-notice').textContent='Your account is valid, but online class data could not load. Please try again.';$('#teacher-login-notice').classList.add('show');return}screen='teacher';render()}
async function signOutTeacher(){await window.classcheckSupabase?.auth.signOut();teacherSession=null;history.replaceState({},'',location.pathname);screen='teacher-login';render()}
function normalizePhone(phone){return phone.replace(/\D/g,'')}
function parentEmail(phone){return `${normalizePhone(phone)}@parents.classcheck.local`}
function loginNotice(message){const notice=$('#login-notice');notice.textContent=message;notice.classList.add('show')}
async function loadParentWorkspace(){const client=window.classcheckSupabase,profileId=parentSession.user.id;const {data:links,error:linksError}=await client.from('student_accounts').select('student_id, students(id,full_name,group_id,groups(id,name,level))').eq('profile_id',profileId);if(linksError)throw linksError;const link=links?.[0],student=link?.students;if(!student)throw new Error('No student is linked');const group=student.groups;const {data:students,error:studentsError}=await client.from('students').select('id,full_name,group_id').eq('group_id',student.group_id);if(studentsError)throw studentsError;const {data:attendance,error:attendanceError}=await client.from('attendance').select('*').in('student_id',students.map(item=>item.id));if(attendanceError)throw attendanceError;onlineStudents=students;db.classes=[{id:group.id,name:group.name,level:group.level||'English',students:students.map(item=>item.full_name)}];db.attendance={};attendance.forEach(item=>{const member=students.find(studentItem=>studentItem.id===item.student_id);if(!member)return;const key=`${group.id}|${item.lesson_date}`;db.attendance[key]||={};db.attendance[key][member.full_name]=item.status});parentStudentId=student.id;parentClass=group.id;parentStudent=student.full_name;parentMonth=[...new Set(allDatesForClass(group.id).map(date=>date.slice(0,7)))].sort().reverse()[0]||today().slice(0,7);save()}
function continuePhone(){const phone=$('#phone-number').value.trim();if(normalizePhone(phone).length<9){loginNotice('Telefon raqamini to‘liq kiriting.');return}authAccess={phone};loginStep='password';render()}
async function createPassword(){const password=$('#new-password').value,confirmPassword=$('#confirm-password').value;if(password.length<6){loginNotice('Parol kamida 6 ta belgidan iborat bo‘lishi kerak.');return}if(password!==confirmPassword){loginNotice('Parollar bir xil emas.');return}const {data,error}=await window.classcheckSupabase.auth.signUp({email:parentEmail(authAccess.phone),password});if(error){loginNotice('Hisob yaratilmadi. Bu raqam avval ro‘yxatdan o‘tgan bo‘lishi mumkin.');return}if(!data.session){loginNotice('Hisob yaratildi, ammo email tasdiqlashi yoqilgan. O‘qituvchidan yordam so‘rang.');return}parentSession=data.session;await claimParentAccess()}
async function claimParentAccess(){const {error}=await window.classcheckSupabase.rpc('claim_parent_access',{p_phone:authAccess.phone});if(error){await window.classcheckSupabase.auth.signOut();loginNotice('Bu telefon raqami o‘qituvchi tomonidan tasdiqlanmagan.');return}try{await loadParentWorkspace();screen='parent';render()}catch{loginNotice('O‘quvchi ma’lumotlari yuklanmadi. O‘qituvchiga murojaat qiling.')}}
async function login(){const password=$('#login-password').value;const {data,error}=await window.classcheckSupabase.auth.signInWithPassword({email:parentEmail(authAccess.phone),password});if(error){loginNotice('Parol noto‘g‘ri yoki bu raqam uchun hisob yaratilmagan.');return}parentSession=data.session;await claimParentAccess()}
async function logoutParent(){await window.classcheckSupabase?.auth.signOut();authAccess=null;parentSession=null;parentStudentId=null;loginStep='phone';screen='login';render()}
function parentLogin(){const phoneView=`<div class="field"><label>Telefon raqami</label><input id="phone-number" type="tel" inputmode="tel" placeholder="+998 90 123 45 67" onkeydown="if(event.key==='Enter')continuePhone()" /></div><div class="notice" id="login-notice"></div><button class="btn primary" onclick="continuePhone()">Davom etish →</button>`;const passwordView=`<p>Farzandingiz qaydini ochish uchun parolni kiriting.</p><div class="field"><label>Parol</label><input id="login-password" type="password" placeholder="Parolni kiriting" onkeydown="if(event.key==='Enter')login()" /></div><div class="notice" id="login-notice"></div><button class="btn primary" onclick="login()">Kirish →</button><button class="switch-link" onclick="loginStep='create';render()">Birinchi marta kelyapsizmi? Parol yarating</button><button class="switch-link" onclick="authAccess=null;loginStep='phone';render()">Boshqa telefon raqami</button>`;const createView=`<p>Bu telefon raqami o‘qituvchi tomonidan oldindan tasdiqlangan bo‘lishi kerak.</p><div class="field"><label>Yangi parol</label><input id="new-password" type="password" placeholder="Kamida 6 ta belgi" /></div><div class="field"><label>Parolni tasdiqlang</label><input id="confirm-password" type="password" placeholder="Parolni qaytadan kiriting" /></div><div class="notice" id="login-notice"></div><button class="btn primary" onclick="createPassword()">Hisob yaratish →</button><button class="switch-link" onclick="loginStep='password';render()">Menda parol bor</button>`;return `<div class="login-page"><section class="login-visual"><div class="brand"><i class="brand-mark"></i>Teacher Muhammaddiyor</div><div><h1>Farzandingizning har bir qadami — <em>natijaga</em> yaqin.</h1><p>Barchasiga birga erishamiz!</p></div><div class="quote">Ota-onalar va o‘quvchilar uchun</div></section><section class="login-panel"><div class="login-form"><div class="eyebrow">OTA-ONA PORTALI</div><h2>${loginStep==='create'?'Yangi hisob yarating':loginStep==='password'?'Xush kelibsiz.':'Farzandingiz qaydini oching.'}</h2>${loginStep==='phone'?`<p>Davom etish uchun tasdiqlangan telefon raqamingizni kiriting.</p>${phoneView}`:loginStep==='password'?passwordView:createView}</div></section></div>`}
function updateStudentOptions(){const c=classById($('#parent-class').value);$('#parent-student').innerHTML='<option value="">Choose a student</option>'+c.students.map(s=>`<option>${s}</option>`).join('')}
function monthLabel(d){return new Date(d+'-01T12:00:00').toLocaleDateString(locale(),{month:'long',year:'numeric'})}
function parent(){const cls=classById(parentClass),dates=allDatesForClass(parentClass).filter(d=>d.startsWith(parentMonth)),total=dates.length,p=dates.filter(d=>attendanceFor(parentClass,d)[parentStudent]==='present').length;const months=[...new Set(allDatesForClass(parentClass).map(d=>d.slice(0,7)))].sort().reverse(),dateHeaders=dates.map(d=>`<th>${new Date(d+'T12:00:00').toLocaleDateString(locale(),{day:'numeric',month:'short'})}</th>`).join(''),cell=(student,d)=>{let st=attendanceFor(parentClass,d)[student];return `<td>${st?`<span class="mark ${st}" title="${st}">${st==='present'?'✓':'×'}</span>`:'<span class="mark none">–</span>'}</td>`};return `<div class="shell"><header class="topbar"><div class="brand"><i class="brand-mark"></i>ClassCheck</div><button class="btn outline" onclick="screen='login';render()">Switch student</button></header><main class="parent-main"><div class="parent-header"><div><div class="eyebrow">Attendance record</div><h1 style="font-family:Fraunces,serif;font-size:40px;letter-spacing:-1.5px;margin:8px 0 0">Hello, ${parentStudent.split(' ')[0]}.</h1><p class="section-subtitle">Here is your lesson attendance in <strong>${cls.name}</strong>.</p></div><div class="class-card" style="margin:0;min-width:180px"><strong>${cls.name}</strong><span>${cls.level} English</span></div></div><div class="student-summary"><div class="summary-card"><div class="stat-label">Lessons this month</div><div class="number">${total}</div></div><div class="summary-card"><div class="stat-label">Lessons attended</div><div class="number" style="color:var(--green)">${p}</div></div><div class="summary-card"><div class="stat-label">Attendance rate</div><div class="number">${total?Math.round(p/total*100):0}%</div></div></div><div class="attendance-box"><div style="padding:20px 22px 0"><h2 class="section-title">Your lesson by lesson record</h2><div class="month-bar"><span>Jump to month:</span><select onchange="parentMonth=this.value;render()">${months.map(m=>`<option value="${m}" ${m===parentMonth?'selected':''}>${monthLabel(m)}</option>`).join('')}</select></div></div><div class="table-wrap"><table class="parent-table"><thead><tr><th>Student</th>${dateHeaders}</tr></thead><tbody><tr><td><div class="student-name">${parentStudent}</div><div class="student-note">${cls.name}</div></td>${dates.map(d=>cell(parentStudent,d)).join('')}</tr></tbody></table></div></div><div class="attendance-box class-overview"><div style="padding:20px 22px 15px"><h2 class="section-title">Class attendance overview</h2><p class="section-subtitle">See the group's attendance for ${monthLabel(parentMonth)}.</p></div><div class="table-wrap"><table class="parent-table"><thead><tr><th>Student</th>${dateHeaders}<th>Rate</th></tr></thead><tbody>${cls.students.map(student=>{const studentPresent=dates.filter(d=>attendanceFor(parentClass,d)[student]==='present').length;return `<tr ${student===parentStudent?'class="current-student"':''}><td><div class="student-name">${student}${student===parentStudent?' <span class="you-label">You</span>':''}</div></td>${dates.map(d=>cell(student,d)).join('')}<td><strong>${total?Math.round(studentPresent/total*100):0}%</strong></td></tr>`}).join('')}</tbody></table></div></div><p class="parent-info">✓ Present &nbsp;&nbsp; × Absent &nbsp;&nbsp; – Not marked yet<br>For questions about an absence, please contact your teacher directly.</p></main></div>`}
function openTeacherProfile(from,editable=false){teacherProfileReturn=from;profileEditable=editable;screen='teacher-profile';render()}
function teacherProfile(){const t=db.teacherProfile,editable=profileEditable;return `<div class="shell"><header class="topbar"><div class="brand"><i class="brand-mark"></i>ClassCheck</div><button class="btn outline" onclick="screen='${teacherProfileReturn}';render()">← Back</button></header><main class="profile-page"><section class="teacher-hero"><img src="teacher-muhammaddiyor-profile.png" alt="Teacher Muhammaddiyor"><div><div class="eyebrow">English language teacher</div><h1>Teacher Muhammaddiyor</h1><p>${t.about}</p>${editable?'<button class="btn primary" onclick="openTeacherProfileEdit()">Edit my profile</button>':''}</div></section><section class="credential-grid"><article><span>IELTS score</span><strong>${t.ielts||'To be added'}</strong></article><article><span>Teaching experience</span><strong>${t.experience||'To be added'}</strong></article><article><span>Teaching style</span><strong>Practical · supportive · goal-focused</strong></article></section><section class="profile-panel"><h2>About my lessons</h2><p>I care about steady progress, encouraging participation, and helping every learner feel more confident using English.</p></section></main></div>`}
function openTeacherProfileEdit(){const t=db.teacherProfile;modal(`<h2>Edit my profile</h2><div class="field"><label>About you</label><input id="teacher-about" value="${t.about}" /></div><div class="field"><label>IELTS score</label><input id="teacher-ielts" value="${t.ielts}" placeholder="e.g. Overall 8.0" /></div><div class="field"><label>Teaching experience</label><input id="teacher-experience" value="${t.experience}" placeholder="e.g. 4 years" /></div><div class="modal-actions"><button class="btn soft" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveTeacherProfile()">Save profile</button></div>`)}
function saveTeacherProfile(){db.teacherProfile={about:$('#teacher-about').value.trim(),ielts:$('#teacher-ielts').value.trim(),experience:$('#teacher-experience').value.trim()};save();closeModal();render()}
function profileKey(classId,student){return `${classId}|${student}`}
function getStudentProfile(classId,student){return db.studentProfiles[profileKey(classId,student)]||{about:'',photo:'',media:[]}}
function openStudentProfile(student,classId,from,editable=false){profileStudent=student;profileClass=classId;profileReturn=from;profileEditable=editable;screen='student-profile';render()}
function studentProfile(){const p=getStudentProfile(profileClass,profileStudent);return `<div class="shell"><header class="topbar"><div class="brand"><i class="brand-mark"></i>ClassCheck</div><button class="btn outline" onclick="screen='${profileReturn}';render()">← Back</button></header><main class="profile-page"><section class="student-hero"><div class="student-photo">${p.photo?`<img src="${p.photo}" alt="${profileStudent}">`:profileStudent.split(' ').map(x=>x[0]).join('').slice(0,2)}</div><div><div class="eyebrow">${classById(profileClass).name}</div><h1>${profileStudent}</h1><p>${p.about||'This student has not added a profile introduction yet.'}</p>${profileEditable?'<button class="btn primary" onclick="openStudentProfileEdit()">Edit my profile</button>':''}</div></section><section class="profile-panel"><div class="profile-panel-heading"><h2>My learning space</h2>${profileEditable?'<button class="btn soft" onclick="openMediaModal()">+ Add photo / video</button>':''}</div>${p.media?.length?`<div class="media-grid">${p.media.map(item=>item.type==='image'?`<img src="${item.src}" alt="Student post">`:`<video src="${item.src}" controls></video>`).join('')}</div>`:'<p>No photos or videos shared yet.</p>'}</section></main></div>`}
function openStudentProfileEdit(){const p=getStudentProfile(profileClass,profileStudent);modal(`<h2>Edit my profile</h2><div class="field"><label>About me</label><input id="student-about" value="${p.about||''}" placeholder="Tell your group a little about yourself" /></div><div class="field"><label>Profile photo</label><input id="student-photo-input" type="file" accept="image/*" /></div><div class="modal-actions"><button class="btn soft" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveStudentProfile()">Save profile</button></div>`)}
function readFile(input,callback){const file=input.files?.[0];if(!file){callback('');return}const reader=new FileReader();reader.onload=()=>callback(reader.result);reader.readAsDataURL(file)}
function saveStudentProfile(){const p=getStudentProfile(profileClass,profileStudent);readFile($('#student-photo-input'),photo=>{db.studentProfiles[profileKey(profileClass,profileStudent)]={...p,about:$('#student-about').value.trim(),photo:photo||p.photo};save();closeModal();render()})}
function openMediaModal(){modal(`<h2>Share media</h2><p>Choose a photo or short video for your group profile.</p><div class="field"><label>Photo or video</label><input id="media-input" type="file" accept="image/*,video/*" /></div><div class="modal-actions"><button class="btn soft" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveMedia()">Add to profile</button></div>`)}
function saveMedia(){const input=$('#media-input'),file=input.files?.[0];if(!file)return;if(file.size>3500000){alert('Please choose a file smaller than 3.5 MB in this prototype.');return}readFile(input,src=>{const p=getStudentProfile(profileClass,profileStudent);p.media||=[];p.media.push({type:file.type.startsWith('video')?'video':'image',src});db.studentProfiles[profileKey(profileClass,profileStudent)]=p;save();closeModal();render()})}
function openResults(classId,from){communityClass=classId;communityReturn=from;screen='results';render()}
function results(){const cls=classById(communityClass),items=db.results[communityClass]||[],teacher=communityReturn==='teacher';return `<div class="shell"><header class="topbar"><div class="brand"><i class="brand-mark"></i>ClassCheck</div><button class="btn outline" onclick="screen='${communityReturn}';render()">← Back</button></header><main class="results-page"><div class="results-intro"><div><div class="eyebrow">${cls.name}</div><h1>Results & feedback</h1><p>Celebrate progress and see teacher feedback for the group.</p></div>${teacher?'<button class="btn primary" onclick="openResultModal()">+ Post a result</button>':''}</div><section class="results-list">${items.length?items.map(item=>`<article class="result-card"><div class="result-initial">${item.student.split(' ').map(x=>x[0]).join('').slice(0,2)}</div><div><span>${item.student}${item.score?` · ${item.score}`:''}</span><h2>${item.title}</h2><p>${item.review}</p></div></article>`).join(''):'<div class="empty">No results have been posted yet.</div>'}</section></main></div>`}
function openResultModal(){const cls=classById(communityClass);modal(`<h2>Post a result</h2><div class="field"><label>Student</label><select id="result-student">${cls.students.map(s=>`<option>${s}</option>`).join('')}</select></div><div class="field"><label>Result / score</label><input id="result-score" placeholder="e.g. 86% or IELTS mock 6.5" /></div><div class="field"><label>Title</label><input id="result-title" placeholder="e.g. Excellent speaking progress" /></div><div class="field"><label>Teacher review</label><input id="result-review" placeholder="Write a short encouraging review" /></div><div class="modal-actions"><button class="btn soft" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveResult()">Post result</button></div>`)}
function saveResult(){const title=$('#result-title').value.trim(),review=$('#result-review').value.trim();if(!title||!review)return;db.results[communityClass]||=[];db.results[communityClass].unshift({student:$('#result-student').value,score:$('#result-score').value.trim(),title,review});save();closeModal();render()}
function openMembers(classId,from){communityClass=classId;communityReturn=from;screen='members';render()}
function members(){const cls=classById(communityClass);return `<div class="shell"><header class="topbar"><div class="brand"><i class="brand-mark"></i>ClassCheck</div><button class="btn outline" onclick="screen='community';render()">← Back</button></header><main class="results-page"><div class="results-intro"><div><div class="eyebrow">${cls.name}</div><h1>Group members</h1><p>Visit classmates’ profiles and get to know your group.</p></div></div><section class="member-grid">${cls.students.map(student=>{const profile=getStudentProfile(communityClass,student);return `<button class="member-card" onclick="openStudentProfile('${student}','${communityClass}','members',${student===parentStudent&&communityReturn==='parent'})">${profile.photo?`<img src="${profile.photo}" alt="${student}">`:`<span>${student.split(' ').map(x=>x[0]).join('').slice(0,2)}</span>`}<strong>${student}</strong><small>${profile.about||'View profile'}</small></button>`}).join('')}</section></main></div>`}
function openCommunity(classId,from){communityClass=classId;communityReturn=from;screen='community';render()}
function community(){const cls=classById(communityClass),posts=db.community[communityClass]||[],homework=db.homework[communityClass],teacher=communityReturn==='teacher';return `<div class="shell"><header class="topbar"><div class="brand"><i class="brand-mark"></i>ClassCheck</div><div class="community-header-actions"><button class="btn outline" onclick="screen='${communityReturn}';render()">← Back</button></div></header><main class="community-main"><div class="community-intro"><div><div class="eyebrow">${cls.level} English · ${cls.students.length} members</div><h1>${cls.name} group space</h1><p>A shared place for questions, lesson discussion, and homework.</p></div>${teacher?'<button class="btn primary" onclick="openHomeworkModal()">+ Share homework</button>':''}</div>${homework?`<section class="homework-card"><div class="homework-icon">✦</div><div><div class="eyebrow">Latest homework</div><h2>${homework.title}</h2><p>${homework.text}</p></div>${teacher?'<button class="homework-edit" onclick="openHomeworkModal()">Edit</button>':''}</section>`:''}<section class="discussion"><div class="discussion-heading"><div><h2>Group discussion</h2><p>Keep messages helpful and related to the group.</p></div><span>${posts.length} posts</span></div><div class="post-list">${posts.length?posts.map(post=>`<article class="post ${post.teacher?'teacher-post':''}"><div class="post-avatar">${post.teacher?'T':post.author.split(' ').map(x=>x[0]).join('').slice(0,2)}</div><div class="post-content"><div class="post-meta"><strong>${post.author}</strong>${post.teacher?'<span>Teacher</span>':''}<time>${post.time}</time></div><p>${post.text}</p></div></article>`).join(''):'<div class="empty">No messages yet. Start the conversation below.</div>'}</div><div class="composer"><div class="post-avatar">${teacher?'T':parentStudent.split(' ').map(x=>x[0]).join('').slice(0,2)}</div><div class="composer-input"><textarea id="post-text" placeholder="Write a message for the group…"></textarea><div><span>Be kind and stay on topic.</span><button class="btn primary" onclick="addPost()">Post message</button></div></div></div></section></main></div>`}
function addPost(){const text=$('#post-text').value.trim();if(!text)return;const teacher=communityReturn==='teacher';db.community[communityClass] ||= [];db.community[communityClass].push({author:teacher?'Teacher':parentStudent,text,time:new Date().toLocaleTimeString(locale(),{hour:'2-digit',minute:'2-digit'}),teacher});save();render()}
function openHomeworkModal(){const item=db.homework[communityClass]||{};modal(`<h2>Share homework</h2><p>This will appear at the top of your group space.</p><div class="field"><label>Homework title</label><input id="homework-title" value="${item.title||''}" placeholder="e.g. Homework for Friday" /></div><div class="field"><label>Instructions</label><input id="homework-text" value="${item.text||''}" placeholder="What should students complete?" /></div><div class="modal-actions"><button class="btn soft" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveHomework()">Share homework</button></div>`)}
function saveHomework(){const title=$('#homework-title').value.trim(),text=$('#homework-text').value.trim();if(!title||!text)return;db.homework[communityClass]={title,text};save();closeModal();render()}
function addCommunityLinks(){if(screen==='teacher'){const navigation=$('.sidebar > div:first-child');const groupButton=document.createElement('button'),resultsButton=document.createElement('button');groupButton.className='nav-item';groupButton.innerHTML='<span class="nav-icon">◌</span>Group space';groupButton.onclick=()=>openCommunity(selectedClass,'teacher');resultsButton.className='nav-item';resultsButton.innerHTML='<span class="nav-icon">★</span>Results';resultsButton.onclick=()=>openResults(selectedClass,'teacher');navigation.append(groupButton,resultsButton)}if(screen==='parent'){const profileButton=document.createElement('button'),resultsButton=document.createElement('button'),groupButton=document.createElement('button');profileButton.className='btn soft group-space-button';profileButton.textContent='My profile';profileButton.onclick=()=>openStudentProfile(parentStudent,parentClass,'parent',true);resultsButton.className='btn soft group-space-button';resultsButton.textContent='Results';resultsButton.onclick=()=>openResults(parentClass,'parent');groupButton.className='btn soft group-space-button';groupButton.textContent='Group space';groupButton.onclick=()=>openCommunity(parentClass,'parent');$('.topbar').querySelector('.btn.outline').before(profileButton,resultsButton,groupButton)}if(screen==='community'){const membersButton=document.createElement('button'),resultsButton=document.createElement('button');membersButton.className='btn soft group-space-button';membersButton.textContent='Members';membersButton.onclick=()=>openMembers(communityClass,communityReturn);resultsButton.className='btn soft group-space-button';resultsButton.textContent='Results';resultsButton.onclick=()=>openResults(communityClass,communityReturn);$('.community-header-actions').prepend(membersButton,resultsButton)}}
function openClassModal(){modal(`<h2>Create a class</h2><p>Set up a new group, then add students to it.</p><div class="field"><label>Class name</label><input id="new-class" placeholder="e.g. B2 Weekend" /></div><div class="field"><label>Level</label><input id="new-level" placeholder="e.g. Upper-intermediate" /></div><div class="modal-actions"><button class="btn soft" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="addClass()">Create class</button></div>`)}
function openStudentModal(){modal(`<h2>Add a student</h2><p>The student will immediately appear on your attendance list.</p><div class="field"><label>Student's full name</label><input id="new-student" placeholder="e.g. Farida Kamilova" onkeydown="if(event.key==='Enter')addStudent()" /></div><div class="modal-actions"><button class="btn soft" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="addStudent()">Add student</button></div>`);setTimeout(()=>$('#new-student').focus(),0)}
function modal(inner){document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><div class="modal">${inner}</div></div>`)}function closeModal(){$('#modal')?.remove()}
async function addClass(){let n=$('#new-class').value.trim(),l=$('#new-level').value.trim();if(!n)return;let id='c'+Date.now();if(teacherSession&&window.classcheckSupabase){const {data,error}=await window.classcheckSupabase.from('groups').insert({name:n,level:l||'English',teacher_id:teacherSession.user.id}).select().single();if(error){alert('The class could not be saved online. Please try again.');return}id=data.id}db.classes.push({id,name:n,level:l||'English',students:[]});save();selectedClass=id;closeModal();render()}
async function addStudent(){let s=$('#new-student').value.trim();if(!s)return;const cls=classById(selectedClass);if(teacherSession&&window.classcheckSupabase){const {data,error}=await window.classcheckSupabase.from('students').insert({group_id:selectedClass,full_name:s}).select().single();if(error){alert('The student could not be saved online. Please try again.');return}onlineStudents.push(data)}cls.students.push(s);save();closeModal();render()}
