function setLanguage(value){language=value;localStorage.setItem('classcheck-language',language);render()}
function addLanguageSwitch(){const host=$('.topbar');if(!host)return;const toggle=document.createElement('div');toggle.className='language-switch';toggle.innerHTML=`<button class="${language==='ENG'?'active':''}" onclick="setLanguage('ENG')">ENG</button><button class="${language==='UZB'?'active':''}" onclick="setLanguage('UZB')">UZB</button>`;host.appendChild(toggle)}
function teacherProfileCard(compact=false){return `<aside class="teacher-profile ${compact?'compact':''}"><img class="teacher-photo" src="teacher-muhammaddiyor-profile.png" alt="Teacher Muhammaddiyor"><div><span>Your teacher</span><strong>Teacher Muhammaddiyor</strong><small>English language teacher</small></div></aside>`}
function addTeacherBranding(){document.querySelectorAll('.brand').forEach(brand=>{brand.innerHTML='<img src="teacher-muhammaddiyor-logo.jpg" alt="Teacher Muhammaddiyor logo" /><span>Teacher Muhammaddiyor</span>'});if(screen==='teacher'){$('.account').innerHTML='<button class="teacher-account" onclick="openTeacherProfile(\'teacher\',true)"><span><strong>Teacher Muhammaddiyor</strong><small>Teacher workspace</small></span><img class="top-logo" src="teacher-muhammaddiyor-logo.jpg" alt="Logo"></button>'}if(screen==='login')$('.login-visual').insertAdjacentHTML('beforeend',teacherProfileCard());if(screen==='parent'){$('.parent-header').insertAdjacentHTML('afterend',teacherProfileCard());$('.parent-header + .teacher-profile').onclick=()=>openTeacherProfile('parent',false)}if(screen==='community'){$('.community-intro').insertAdjacentHTML('beforeend',teacherProfileCard(true));$('.community-intro .teacher-profile').onclick=()=>openTeacherProfile('community',false)}}
function applyLanguage(){document.title=language==='UZB'?'ClassCheck — davomat oson':'ClassCheck — attendance made simple';if(language!=='UZB')return;const walker=document.createTreeWalker($('#app'),NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);const entries=Object.entries(uzb).sort((a,b)=>b[0].length-a[0].length),translate=text=>{let value=text;entries.forEach(([english,uzbek])=>{value=value.split(english).join(uzbek)});return value};nodes.forEach(node=>node.nodeValue=translate(node.nodeValue));$('#app').querySelectorAll('[placeholder],[title]').forEach(element=>{['placeholder','title'].forEach(attribute=>{if(element.hasAttribute(attribute))element.setAttribute(attribute,translate(element.getAttribute(attribute)))})})}
function openParentAccessModal(student){accessStudent=student;const access=db.parentAccess[`${selectedClass}|${student}`]||{};modal(`<h2>Parent access</h2><p>Add the parent’s phone number. Only approved numbers can create an account through the shared parent link.</p><div class="field"><label>Parent phone number</label><input id="parent-phone" type="tel" value="${access.phone||''}" placeholder="+998 90 123 45 67" /></div><div class="modal-actions"><button class="btn soft" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveParentAccess()">Save access</button></div>`)}
async function saveParentAccess(){const phone=$('#parent-phone').value.trim();if(normalizePhone(phone).length<9)return;const key=`${selectedClass}|${accessStudent}`,current=db.parentAccess[key]||{};if(teacherSession){const student=onlineStudents.find(item=>item.group_id===selectedClass&&item.full_name===accessStudent);const {error}=await window.classcheckSupabase.from('students').update({parent_phone:phone}).eq('id',student.id);if(error){alert('Telefon raqami onlayn saqlanmadi.');return}student.parent_phone=phone}db.parentAccess[key]={...current,phone};save();closeModal();render()}
async function removeStudent(name){if(!confirm(`Remove ${name} from this class? Their attendance record in this class will also be removed.`))return;const student=onlineStudents.find(item=>item.group_id===selectedClass&&item.full_name===name);if(teacherSession&&student){const {error}=await window.classcheckSupabase.from('students').delete().eq('id',student.id);if(error){alert('The student could not be removed online.');return}onlineStudents=onlineStudents.filter(item=>item.id!==student.id)}const cls=classById(selectedClass);cls.students=cls.students.filter(s=>s!==name);Object.keys(db.attendance).filter(k=>k.startsWith(selectedClass+'|')).forEach(k=>delete db.attendance[k][name]);delete db.parentAccess[`${selectedClass}|${name}`];save();render()}
async function removeClass(){const cls=classById(selectedClass);if(db.classes.length===1){alert('Keep at least one class in ClassCheck. You can rename it or add another class first.');return}if(!confirm(`Delete ${cls.name}? This permanently removes all students and attendance records for this class.`))return;if(teacherSession){const {error}=await window.classcheckSupabase.from('groups').delete().eq('id',selectedClass);if(error){alert('The class could not be removed online.');return}onlineStudents=onlineStudents.filter(item=>item.group_id!==selectedClass)}db.classes=db.classes.filter(c=>c.id!==selectedClass);Object.keys(db.attendance).filter(k=>k.startsWith(selectedClass+'|')).forEach(k=>delete db.attendance[k]);Object.keys(db.parentAccess).filter(k=>k.startsWith(selectedClass+'|')).forEach(k=>delete db.parentAccess[k]);selectedClass=db.classes[0].id;save();render()}
function addTeacherDeleteControls(){const hero=$('.hero');const deleteClass=document.createElement('button');deleteClass.className='btn danger';deleteClass.textContent='Delete class';deleteClass.onclick=removeClass;hero.querySelector('.btn.primary').before(deleteClass);document.querySelectorAll('.teacher-table tbody tr').forEach((row,index)=>{const student=classById(selectedClass).students[index],accessCell=document.createElement('td'),accessButton=document.createElement('button'),removeCell=document.createElement('td'),removeButton=document.createElement('button');accessButton.className='access-student';accessButton.textContent=db.parentAccess[`${selectedClass}|${student}`]?.phone?'Access set':'Set access';accessButton.onclick=()=>openParentAccessModal(student);removeButton.className='remove-student';removeButton.textContent='Remove';removeButton.onclick=()=>removeStudent(student);accessCell.appendChild(accessButton);removeCell.appendChild(removeButton);row.append(accessCell,removeCell)});const headRow=$('.teacher-table thead tr');headRow.append(document.createElement('th'),document.createElement('th'))}
function render(){if(screen==='login'){language='UZB';localStorage.setItem('classcheck-language',language)}$('#app').innerHTML=screen==='teacher-login'?teacherLoginPage():screen==='teacher'?teacher():screen==='login'?parentLogin():screen==='parent'?parent():screen==='community'?community():screen==='teacher-profile'?teacherProfile():screen==='student-profile'?studentProfile():screen==='members'?members():results();if(screen==='teacher')addTeacherDeleteControls();if(screen==='teacher'||screen==='parent'||screen==='community')addCommunityLinks();if(screen==='parent')$('.topbar .btn.outline').onclick=logoutParent;addTeacherBranding();addLanguageSwitch();applyLanguage()}
render();

// On phones, turn wide attendance tables into readable lesson-by-lesson cards.
function labelParentAttendanceCells(){
  if(screen!=='parent') return;
  document.querySelectorAll('.parent-table').forEach(table=>{
    const headings=[...table.querySelectorAll('thead th')].slice(1).map(cell=>cell.textContent.trim());
    table.querySelectorAll('tbody tr').forEach(row=>{
      [...row.querySelectorAll('td')].slice(1).forEach((cell,index)=>cell.dataset.date=headings[index]||'Davomat');
    });
  });
}
const renderClassCheckPage=render;
render=function(){renderClassCheckPage();labelParentAttendanceCells()};
